{
  "complexity": "normal",
  "requiredCapabilities": ["business strategy and financial logic", "brand strategy and channel conflict mitigation"],
  "assignments": [
    { "agentId": "business_strategist", "mission": "Evaluate options A/B/C using given constraints (capacity, margins, cash flow, contract terms). Choose one option and articulate: key reason, strongest counterargument, pivotal assumption that could flip the choice, and a 3-year operational plan to manage the chosen path’s biggest risk. Use only provided info; state conditionals where data is missing.", "priority": "high" },
    { "agentId": "brand_creative", "mission": "Assess brand equity and channel-conflict risks across A/B/C. For the selected option, design a concrete 3-year plan to protect the self-owned brand (positioning, SKU/recipe differentiation, scarcity management, seasonality allocation, messaging, and founder bandwidth relief) within fixed capacity and timing limits.", "priority": "medium" }
  ],
  "requiresRedTeam": false,
  "reason": "Decision hinges on financial/operational tradeoffs and brand/channel risk. A business strategist selects and justifies the path; a brand strategist crafts the mitigation plan. No external research is needed to decide, so two specialists are sufficient."
}

{
  "complexity": "normal",
  "requiredCapabilities": ["商業與風險決策（資源負荷、合約義務、機會成本）", "品牌與設計主導權策略（署名、風格一致性、長期定位）"],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "基於題目現有資訊評估A/B/C之可行性與風險：主持建築師出席負荷、現有三案合約義務、審查密集度、行政能量缺口、全有全無與時程風險、等待的機會成本。提出單一明確選項，列出會翻盤的關鍵條件，以及投標/簽約時對責任分工、出席義務、時程與風險移轉的不可妥協條款。",
      "priority": "high"
    },
    {
      "agentId": "brand_creative",
      "mission": "評估共同投標對品牌：風格稀釋、署名並列、作品集影響與未來接案動能。提出降低風格保守化的治理機制（設計決策權限、審美準則、關鍵節點否決權）、作品發表與案例敘事規範，並定義不可妥協的品牌/署名條件與可能使決策翻盤的品牌面臨風險指標。",
      "priority": "medium"
    }
  ],
  "requiresRedTeam": false,
  "reason": "決策同時關涉執行風險與品牌主導權取捨；商業風險與品牌影響是兩個獨立關鍵面，需各一位專家即足夠。無需額外市場研究，因題目限制僅用既有資訊判斷。"
}

{
  "complexity": "deep",
  "requiredCapabilities": ["business strategy", "financial analysis", "risk assessment", "decision under uncertainty"],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "Choose A/B/C using only the test data. Reconcile survey vs behavior (stated vs revealed preference). Flag the most overinterpreted metric and why. State what specific new results would change the choice. Judge if evidence supports a 3‑year structural reallocation and under what conditions/risks. Deliver a concise, defensible recommendation.",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "This is a high‑stakes structural decision needing strategic, financial, and risk trade‑off analysis only; no external research or brand work is required. One strategist suffices."
}
